refsection.programlisting:
// GF(16) with the default primitive polynomial 1 + x + x^4
F = gf_create_field(2, 4);
F(3)              // [1 1 0 0 1]
F(4)(1:6, :)      // 0, 1, alpha, alpha^2, alpha^3, alpha^4 = 1 + alpha

// The same field built from another primitive polynomial: 1 + x^3 + x^4
G = gf_create_field(2, 4, [1 0 0 1 1]);

// 1 + x + x^2 + x^3 + x^4 is irreducible but not primitive
try
    gf_create_field(2, 4, [1 1 1 1 1]);
catch
    disp(lasterror())
end

// The prime field GF(7); its default polynomial is x - 3 = x + 4
P = gf_create_field(7, 1);
P(3)              // [4 1]
